const TILE=64,SAVE='hearthvale-save-v1';let freshStart=!localStorage.getItem(SAVE);const terrain=(x,y)=>city.terrain(x,y);let city,scene,tool='inspect',speed=1,paused=false,selected=null,selectionSignature='',toastTimer,saveClock=0;
