function palisadePoints(mask,cx,cy){const points=new Map(),add=(x,y)=>points.set(x+','+y,[x,y]);for(const x of [-8,0,8])for(const y of [-8,0,8])add(cx+x,cy+y);for(const[bit,dx,dy]of [[1,0,-1],[2,1,0],[4,0,1],[8,-1,0]])if(mask&bit)for(const offset of [-8,0,8])for(const d of [8,16,24,32])add(cx+dx*d-dy*offset,cy+dy*d+dx*offset);return [...points.values()].sort((a,b)=>a[1]-b[1]||a[0]-b[0]);}
function paintRoadNetwork(rc,roads,styles=[[32,'#977653',0,0],[28,'#D4B568',-.5,1]],details=true){const points=new Map([...roads].map(k=>{const[x,y]=k.split(',').map(Number),hash=((x*73856093)^(y*19349663))>>>0;return [k,{x,y,px:x*TILE+32+(hash%7-3)*.35,py:y*TILE+32+((hash>>>6)%7-3)*.35}];}));for(const [width,color,dx,dy]of styles){rc.save();rc.translate(dx,dy);rc.lineWidth=width;rc.lineCap=rc.lineJoin='round';rc.strokeStyle=rc.fillStyle=color;rc.beginPath();for(const p of points.values()){rc.moveTo(p.px+width/2,p.py);rc.arc(p.px,p.py,width/2,0,Math.PI*2);}rc.fill();rc.beginPath();for(const p of points.values())for(const [ax,ay]of [[1,0],[0,1]]){const n=points.get(key(p.x+ax,p.y+ay));if(!n)continue;rc.moveTo(p.px,p.py);const bend=Math.sin(p.x*3.17+p.y*7.13)*1.4;rc.quadraticCurveTo((p.px+n.px)/2+ay*bend,(p.py+n.py)/2-ax*bend,n.px,n.py);}rc.stroke();rc.restore();}const counts={stones:0,scuffs:0};if(!details)return counts;for(const p of points.values()){const h=((p.x*73856093)^(p.y*19349663))>>>0;if(h%100<8){counts.stones++;rc.fillStyle='#A49A80';rc.beginPath();rc.ellipse(p.px+5,p.py+2,2.5,1.6,.3,0,Math.PI*2);rc.fill();rc.fillStyle='#D1C5A6';rc.fillRect(p.px+4,p.py+1,2,1);if(h%3===0){rc.fillStyle='#A49A80';rc.fillRect(p.px+1,p.py-2,2,1);}}else if(h%100<15){counts.scuffs++;rc.fillStyle='#C5944B';rc.beginPath();rc.ellipse(p.px-4,p.py+3,2,.6,-.2,0,Math.PI*2);rc.fill();}}return counts;}
function paintPavedRoadNetwork(rc,roads,paved,source,frames){if(!paved.size||!frames?.length)return;const tiles=new Set(),transitions=[];for(const k of paved){if(!roads.has(k))continue;tiles.add(k);const[x,y]=k.split(',').map(Number);for(const[dx,dy]of [[1,0],[-1,0],[0,1],[0,-1]]){const n=key(x+dx,y+dy);if(roads.has(n)&&!paved.has(n)){tiles.add(n);transitions.push({x:x*TILE+32+dx*32,y:y*TILE+32+dy*32,dx,dy});}}}const layer=document.createElement('canvas');layer.width=W*TILE;layer.height=H*TILE;const c=layer.getContext('2d'),seen=new Set();for(const k of tiles){const[tx,ty]=k.split(',').map(Number);for(let gy=Math.floor(ty*TILE/6.5)-1;gy<=Math.ceil((ty+1)*TILE/6.5);gy++)for(let gx=Math.floor(tx*TILE/11)-1;gx<=Math.ceil((tx+1)*TILE/11);gx++){const id=gx+','+gy;if(seen.has(id))continue;seen.add(id);const hash=((gx*73856093)^(gy*19349663))>>>0,x=gx*11+(gy%2)*5.5+5.5,y=gy*6.5+3.25,inside=paved.has(key(Math.floor(x/TILE),Math.floor(y/TILE)));let probability=inside?1:0;for(const t of transitions){const along=(x-t.x)*t.dx+(y-t.y)*t.dy,cross=Math.abs((x-t.x)*t.dy-(y-t.y)*t.dx);if(Math.abs(along)>24||cross>30)continue;const p=(24-along)/48;probability=inside?Math.min(probability,p):Math.max(probability,p);}if((hash%1000)/1000>=probability)continue;const r=frames[hash%frames.length],fit=Math.min(9.8/r.width,6.6/r.height),w=r.width*fit,h=r.height*fit;c.drawImage(source,r.x,r.y,r.width,r.height,x-w/2,y-h/2,w,h);}}const mask=document.createElement('canvas');mask.width=layer.width;mask.height=layer.height;paintRoadNetwork(mask.getContext('2d'),roads,[[28,'#fff',-.5,1]],false);c.globalCompositeOperation='destination-in';c.drawImage(mask,0,0);rc.drawImage(layer,0,0);}

function toast(text){$('toast').textContent=text;ResourceUI.decorate($('toast'));$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3400);}
